fn webhook_server_start(cfg: AgentConfig) -> Result<void, string>
  intent "Webhook HTTP 서버 메인 루프"
  do
    print("🚀 Self-Healing Agent Webhook Server")
    print("   주소: " + cfg.webhook_host + ":" + int_to_str(cfg.webhook_port))
    print("   엔드포인트:")
    print("     POST /webhook/push    - GOGS push 이벤트")
    print("     POST /webhook/ci      - CI 실패 이벤트")
    print("     POST /webhook/manual  - 수동 트리거")
    print("     GET  /health          - 헬스체크")
    print("     GET  /status          - 현재 상태")

    // 소켓 생성
    let server_fd_result = socket_create()
    match server_fd_result
      Err(e) => return Err("소켓 생성 실패: " + e)
      Ok(server_fd) => {
        // SO_REUSEADDR
        socket_set_reuse_addr(server_fd)

        // 바인드
        match socket_bind(server_fd, cfg.webhook_host, cfg.webhook_port)
          Err(e) => return Err("바인드 실패: " + e)
          Ok(_) => {}
        end

        // 리슨
        match socket_listen(server_fd, 128)
          Err(e) => return Err("리슨 실패: " + e)
          Ok(_) => {}
        end

        print("✅ 서버 준비 완료")

        // Accept 루프
        return accept_loop(server_fd, cfg)
      }
    end
end

